func typeKind(value *syntax.Expression) SymbolKind {
	if value == nil {
		return NewSymbolKindType()
	}
	switch value.Tag() {
	case syntax.ExpressionTagStructType:
		return NewSymbolKindStruct()
	case syntax.ExpressionTagInterfaceType:
		return NewSymbolKindInterface()
	default:
		return NewSymbolKindType()
	}
}

func receiverName(
	pkg *sourceanalysis.Package,
	declaration *syntax.FunctionDeclaration,
) string {
	object, _ := pkg.Facts.DefinitionName(declaration.Name).(*types.Func)
	if object == nil {
		return pkg.Path
	}
	signature, _ := object.Type().(*types.Signature)
	operand := signature == nil
	if !operand {
		operand = signature.Recv() == nil
	}
	if operand {
		return pkg.Path
	}
	value := signature.Recv().Type()
	for {
		pointer, ok := value.(*types.Pointer)
		if !ok {
			break
		}
		value = pointer.Elem()
	}
	named, _ := types.Unalias(value).(*types.Named)
	if named == nil {
		return pkg.Path
	}
	return named.Obj().Name()
}

func appendTGoFieldSymbols(
	result []Symbol,
	pkg *sourceanalysis.Package,
	uri string,
	fields []*syntax.TGoField,
	container string,
) []Symbol {
	for _, field := range fields {
		for _, name := range field.Field.Names {
			result = appendSymbol(
				result,
				pkg,
				uri,
				name.Name, NewSymbolKindField(), container,
				field.Field.Span,
				name.Span,
			)
		}
		result = appendEmbeddedFieldSymbol(
			result, pkg, uri, field.Field, container,
		)
	}
	return result
}

